"""Page shell for server-side rendering; dynamic values are escaped by rendering.py."""

PAGE = r'''
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f7f6f2"><title>Hanoi Temp — Today, through the years</title>
<style>

:root{--paper:#f7f6f2;--ink:#263c36;--muted:#78817a;--line:#dedfd6;--orange:#d86435;--pale:#eee9df}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 Arial,Helvetica,sans-serif}button,input,select{font:inherit}button,a,input,select{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--orange);outline-offset:4px}header{max-width:1320px;margin:auto;padding:27px 48px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font-size:22px;font-weight:750;letter-spacing:-1px;display:flex;align-items:center;gap:10px}.brand svg{width:26px;height:30px;color:var(--orange)}nav{display:flex;align-items:center;gap:30px;font-size:13px}nav a{text-decoration:none}.location{border-left:1px solid var(--line);padding-left:26px;display:flex;align-items:center;gap:8px}.pin{width:7px;height:7px;background:var(--orange);border-radius:50%}main{max-width:1224px;padding:0 0 30px;margin:auto}.intro{display:flex;align-items:end;justify-content:space-between;padding:42px 0 28px;gap:24px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;font-weight:700;color:var(--muted);margin:0 0 12px}h1{font:normal clamp(35px,4vw,51px)/1.12 Georgia,serif;letter-spacing:-1.7px;margin:0 0 11px}h1 em{color:var(--orange);font-weight:normal}.sub{margin:0;color:var(--muted);font-size:14px}.hero{margin-top:28px;border:1px solid var(--line);border-radius:12px;background:#fff;display:grid;grid-template-columns:1fr 1.28fr;overflow:hidden}.weather{padding:29px 34px;position:relative}.card-top{display:flex;justify-content:space-between;align-items:center;font-size:13px}.badge{background:#f5eee4;color:#97794e;padding:4px 9px;border-radius:4px;font-size:10px;letter-spacing:.5px}.temp-row{display:flex;align-items:center;gap:30px;margin:10px 0 0}.temp{font-size:87px;letter-spacing:-6px;line-height:1.2;font-weight:400}.temp small{font-size:33px;letter-spacing:-2px;vertical-align:top;display:inline-block;padding-top:13px}.sun{width:68px;height:68px;color:#d99b43}.weather-note{color:var(--muted);font-size:12px}.compare{padding:30px 34px;background:#f0f2e9;border-left:1px solid var(--line);display:flex;flex-direction:column;justify-content:center}.comparison{font:normal 31px/1.25 Georgia,serif;letter-spacing:-.7px;margin:9px 0 12px}.comparison span{color:var(--orange)}.compare p{margin:0;color:#788172;font-size:13px;max-width:390px}.baseline{margin-top:21px;display:flex;align-items:center;gap:10px;font-size:11px;color:#667262}.baseline:before{content:"";width:24px;border-top:2px dashed #9b9e81}.chart-card{margin-top:25px;border:1px solid var(--line);background:white;border-radius:12px;padding:26px 30px 18px}.chart-header{display:flex;align-items:center;justify-content:space-between;gap:20px}h2{font:normal 24px/1.3 Georgia,serif;letter-spacing:-.5px;margin:0 0 5px}.chart-header p{font-size:12px;color:var(--muted);margin:0}.segments{display:flex;gap:3px;padding:4px;border:1px solid #e6e6de;background:var(--paper);border-radius:6px}.segments a{border:0;border-radius:4px;padding:7px 13px;background:transparent;color:var(--muted);font-size:11px}.segments a[aria-current=page]{background:white;color:var(--ink);box-shadow:0 1px 4px #00000012}.chart-wrap{position:relative;margin-top:20px}#chart{display:block;width:100%;height:auto;overflow:visible}.chart-foot{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #efefe9;padding-top:14px;font-size:10px;color:var(--muted);gap:16px}.legend{display:flex;align-items:center;gap:17px;flex-wrap:wrap}.legend span{display:flex;align-items:center;gap:6px}.dot{width:6px;height:6px;border-radius:50%;background:#8f9b85}.dot.orange{background:var(--orange)}.dash{width:17px;border-top:2px dashed #a5a68c}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:17px;margin-top:22px}.stat{padding:21px 24px;border:1px solid var(--line);border-radius:9px;display:flex;justify-content:space-between;align-items:center}.stat-label{font-size:11px;color:var(--muted);margin-bottom:7px}.stat-value{font-size:27px;letter-spacing:-1px}.stat-value small{font-size:12px;color:var(--muted);letter-spacing:0;margin-left:8px}.stat-icon{font-size:25px;color:#a6afa0}.warm .stat-icon{color:var(--orange)}.cold .stat-icon{color:#829fa3}.note{margin-top:26px;display:flex;justify-content:space-between;align-items:start;gap:40px;padding:0 3px}.note-copy{max-width:700px}.note h3{font:normal 18px Georgia,serif;margin:0 0 7px}.note p{font-size:12px;color:var(--muted);margin:0;line-height:1.7}.note a{font-size:12px;white-space:nowrap;text-underline-offset:4px}footer{max-width:1224px;margin:0 auto;padding:21px 0 25px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;font-size:10px;color:var(--muted)}.demo-indicator{display:inline-flex;align-items:center;gap:6px}.demo-indicator:before{content:"";width:5px;height:5px;border-radius:50%;background:var(--orange)}details{margin-top:22px;border-top:1px solid var(--line);padding:18px 3px;color:var(--muted);font-size:12px}summary{cursor:pointer;color:var(--ink)}details p{max-width:820px;line-height:1.8}.tooltip{position:absolute;pointer-events:none;background:var(--ink);color:white;padding:9px 12px;border-radius:6px;font-size:12px;box-shadow:0 4px 20px #0002;transform:translate(-50%,-110%);z-index:2;white-space:nowrap}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.chart-summary{font-size:11px;color:var(--muted);margin:8px 0 0;min-height:17px} @media(min-width:1500px){main,footer{max-width:1224px}.intro{padding-top:52px}}@media(max-width:1320px){main,footer{margin-left:48px;margin-right:48px}}@media(max-width:760px){header{padding:20px 22px}nav{gap:16px}.location{padding-left:16px}main,footer{margin-left:22px;margin-right:22px}.intro{align-items:start;flex-direction:column;padding-top:29px;gap:21px}h1{font-size:40px}.hero{grid-template-columns:1fr}.weather{padding:24px}.compare{border-left:0;border-top:1px solid var(--line);padding:24px}.comparison{font-size:29px}.temp{font-size:77px}.chart-card{padding:23px 17px 16px}.chart-header{align-items:start;flex-direction:column;gap:16px}.chart-header h2{font-size:22px}.segments{align-self:start}.chart-foot{align-items:start;flex-direction:column;gap:10px}.stats{gap:9px}.stat{padding:15px 12px;align-items:start}.stat-value{font-size:23px}.stat-value small{display:block;margin:3px 0 0;font-size:11px}.stat-icon{display:none}.note{gap:14px;flex-direction:column}.note p{font-size:11px}footer{flex-direction:column;gap:8px}.brand{font-size:19px}nav a{font-size:12px}.location{font-size:11px}.chart-summary{font-size:10px}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s}@keyframes enter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}}

.year-details{margin-top:25px;border:1px solid var(--line);border-radius:12px;background:white;overflow:hidden}.table-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 30px 20px}.table-heading p{margin:0;color:var(--muted);font-size:12px}.table-count{font-size:11px;color:var(--muted);white-space:nowrap}.table-scroll{max-height:420px;overflow:auto;scrollbar-color:#c7cbbf transparent}.year-table{border-collapse:separate;border-spacing:0;width:100%;font-size:13px;white-space:nowrap;font-variant-numeric:tabular-nums}.year-table th,.year-table td{padding:14px 24px;border-bottom:1px solid #eeeee7;text-align:right}.year-table th:first-child,.year-table td:first-child,.year-table th:last-child,.year-table td:last-child{text-align:left}.year-table thead th{position:sticky;top:0;background:#f7f8f3;color:var(--muted);font-size:10px;font-weight:600;letter-spacing:.7px;text-transform:uppercase;z-index:1}.year-table tbody th{font-weight:500;text-align:left}.year-table tbody tr:hover{background:#fafaf6}.year-table .active-metric{background:#f3f4ed;color:var(--ink);font-weight:600}.year-table thead .active-metric{background:#e9eddf}.year-table .current-year td,.year-table .current-year th{color:var(--orange);background:#fcf3ed}.year-table .current-year .active-metric{background:#fae9dd}.row-status{color:var(--muted);font-size:11px}.row-status.forecast{color:var(--orange)}.table-footer{padding:13px 30px;font-size:10px;color:var(--muted);border-top:1px solid var(--line)}@media(max-width:760px){.table-heading{padding:20px 17px;align-items:start;flex-direction:column;gap:8px}.year-table th,.year-table td{padding:13px 16px}.table-footer{padding:13px 17px}.year-details h2{font-size:22px}}
.icon-button{border:1px solid var(--line);background:white;border-radius:4px;color:var(--ink);padding:5px 12px;font-size:12px;margin-left:12px}.segments a:disabled{opacity:.5;cursor:wait}.data-warning{color:#a15b31!important}

.segments a{text-decoration:none;display:block}.methodology{border-top:1px solid var(--line);margin-top:22px;padding:18px 3px;font-size:12px;color:var(--muted)}.methodology h3{color:var(--ink);font:18px Georgia,serif}.methodology p{max-width:820px;line-height:1.8}.chart-point:hover,.chart-point:focus{stroke:var(--ink);stroke-width:2}

</style>
</head>
<body>
<header><div class="brand"><svg viewBox="0 0 24 30" fill="none" aria-hidden="true"><path d="M9 17V6a3 3 0 0 1 6 0v11a6 6 0 1 1-6 0Z" stroke="currentColor" stroke-width="1.7"/><path d="M12 11v11" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="23" r="2" fill="currentColor"/><path d="M18 7h3m-3 5h2" stroke="currentColor" stroke-width="1.5"/></svg>hanoi temp<span style="color:var(--orange)">.</span></div><nav aria-label="Main"><a href="#about">About the data ↗</a><span class="location"><i class="pin"></i> Hanoi, Vietnam</span></nav></header>
<main>
<p class="{{status_class}}" id="data-status" role="status" style="color:var(--muted);font-size:12px;margin:20px 0 0">{{data_status}}</p><section class="hero" aria-label="Temperature comparison"><div class="weather"><div class="card-top"><span id="day-title">{{day_title}}</span><span class="badge">{{forecast_badge}}</span></div><div class="temp-row"><div class="temp"><span id="temperature">{{temperature}}</span><small>°C</small></div><svg class="sun" viewBox="0 0 80 80" fill="none" aria-hidden="true"><circle cx="40" cy="40" r="17" fill="#f7e4bc" stroke="currentColor" stroke-width="1.5"/><g stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M40 8v8M40 64v8M8 40h8M64 40h8M17 17l6 6M57 57l6 6M17 63l6-6M57 23l6-6"/></g></svg></div><div class="weather-note" id="metric-label">{{metric_label}}</div></div><div class="compare" aria-live="polite"><div class="eyebrow" style="margin:0">A date with history</div><div class="comparison"><span id="anomaly">{{anomaly}}</span><br><span id="comparison-caption" style="color:inherit">{{comparison_caption}}</span></div><p id="compare-copy">{{compare_copy}}</p><div class="baseline" id="baseline">{{baseline}}</div></div></section>
<section class="chart-card" aria-labelledby="chart-title"><div class="chart-header"><div><h2 id="chart-title">One day. Decades of weather.</h2><p id="chart-subtitle">{{chart_subtitle}}</p></div><nav class="segments" aria-label="Temperature metric">{{metric_links}}</nav></div><div class="chart-wrap"><svg id="chart" viewBox="0 0 1100 260" role="img" aria-labelledby="chart-title chart-description">{{chart}}</svg></div><p class="chart-summary" id="chart-description">{{chart_description}}</p><div class="chart-foot"><div class="legend"><span><i class="dot"></i> ERA5 history</span><span><i class="dash"></i> 1991–2020 baseline</span><span><i class="dot orange"></i> Today · forecast</span></div><span>Hover a point for details · Full values in the table</span></div></section>
<section class="stats" aria-label="Historical highlights"><div class="stat warm"><div><div class="stat-label">Warmest on this day</div><div class="stat-value" id="warmest">{{warmest}}</div></div><span class="stat-icon" aria-hidden="true">↗</span></div><div class="stat cold"><div><div class="stat-label">Coldest on this day</div><div class="stat-value" id="coldest">{{coldest}}</div></div><span class="stat-icon" aria-hidden="true">↘</span></div><div class="stat"><div><div class="stat-label">Years of perspective</div><div class="stat-value" id="years">{{years}}</div></div><span class="stat-icon" aria-hidden="true">◷</span></div></section>
<section class="year-details" aria-labelledby="table-title"><div class="table-heading"><div><h2 id="table-title">The details, year by year.</h2><p id="table-subtitle">{{table_subtitle}}</p></div><span class="table-count" id="table-count">{{table_count}}</span></div><div class="table-scroll" role="region" aria-label="Yearly temperatures, scroll to view earlier years" tabindex="0"><table class="year-table"><caption class="sr-only">Temperatures for today's calendar date in Hanoi, newest year first. Temperatures are in Celsius.</caption><thead><tr><th scope="col">Year</th><th scope="col" class="{{mean_column}}">Daily mean (°C)</th><th scope="col" class="{{high_column}}">High (°C)</th><th scope="col" class="{{low_column}}">Low (°C)</th><th scope="col">Data source</th></tr></thead><tbody id="year-rows">{{year_rows}}</tbody></table></div><div class="table-footer">Newest first · Scroll for earlier years · Today is a forecast; historical values are ERA5 estimates.</div></section>
<section class="note"><div class="note-copy"><h3>A single day tells a story. History gives it context.</h3><p>Weather changes from year to year. This view compares the same calendar day across the decades — a small window into Hanoi’s past, and a little perspective on the present.</p></div><a href="#about">How to read this chart ↗</a></section>
<section id="about" class="methodology"><h3>About the data</h3><p>Historical daily mean, high, and low temperatures are reconstructed estimates from Open-Meteo’s ERA5 dataset for central Hanoi (21.0285°N, 105.8542°E), starting in 1940. They represent a model grid cell, not a single local weather station. Each day runs from midnight to midnight in Hanoi (UTC+7).</p><p>Today’s values are full-day forecasts from Open-Meteo’s Forecast API. They may change and are shown separately from historical estimates. ERA5 data arrives with a delay, so recent historical dates are reconciled regularly. A comparison baseline uses this calendar day in 1991–2020; if any baseline year is missing, the comparison is withheld. February 29 uses leap years only. A single day’s chart does not measure the overall climate trend.</p><p>Weather data by <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Historical reanalysis: <a href="https://doi.org/10.24381/cds.adbb2d47" target="_blank" rel="noopener noreferrer">ERA5 / Copernicus Climate Change Service (C3S), ECMWF</a>. <a href="https://open-meteo.com/en/docs/historical-weather-api" target="_blank" rel="noopener noreferrer">Dataset documentation ↗</a>.</p></section>
</main><footer><span>hanoi temp. &nbsp; Made for the weather-curious. &nbsp; <a href="https://github.com/buikhacnam" target="_blank" rel="noopener noreferrer">GitHub ↗</a></span><span class="demo-indicator">Hanoi time (UTC+7) · Temperatures in °C</span></footer>

</body></html>
'''
